// ── pipeline config.mjs ──
// Config for the docs -> lorebook conversion pipeline.
// Paths are relative to the Marinara Engine `docs/` folder.

const TARGET_DOCS = [
  // Conversation guide (initial practice bot lives in Conversation mode)
  "conversation/getting-started.md",
  "conversation/calls.md",
  "conversation/emoji-stickers-gifs.md",
  "conversation/profiles.md",
  "conversation/schedules.md",
  "conversation/selfies.md",
  "conversation/table-games.md",

  // FAQ / Troubleshooting
  "FAQ.md",
  "TROUBLESHOOTING.md",

  // Lorebook guide
  "lorebooks/overview.md",
  "lorebooks/entries.md",
  "lorebooks/import-export.md",

  // Preset guide
  "prompts/presets.md",
  "chats/settings-profiles.md",

  // Macro guide
  "prompts/macros.md",

  // Noodle guide
  "noodle/overview.md",
  "noodle/settings.md",
];

// Sections with these exact headings are dropped everywhere (cross-link
// lists, not knowledge content).
const DROP_SECTION_HEADINGS = new Set(["related guides"]);

// Max characters per lorebook entry before we split further.
const MAX_ENTRY_CHARS = 1500;

// Section heading words to ignore when deriving keys.
const STOPWORDS = new Set([
  "the", "a", "an", "and", "or", "for", "to", "in", "of", "on", "with",
  "your", "you", "is", "are", "how", "what", "when", "where", "why",
  "this", "that", "guide", "overview", "settings", "using",
]);

// Bilingual synonym augmentation: if a section's heading+content contains
// any of `match` (case-insensitive substring), all `keys` are added to
// that entry's trigger keywords. This applies regardless of which file the
// section came from, per the beginner keyword coverage spec.
const KEYWORD_MAP = [
  { match: ["lorebook", "world info"], keys: ["로어북", "lorebook", "world info"] },
  { match: ["preset"], keys: ["프리셋", "preset", "prompt"] },
  { match: ["connection", "provider", "api key"], keys: ["커넥션", "connection", "API 키", "provider"] },
  { match: ["agent"], keys: ["에이전트", "agent"] },
  { match: ["schedule", "autonomous"], keys: ["스케줄", "schedule", "자율 메시지", "먼저 연락", "autonomous"] },
  { match: ["selfie", "image generation"], keys: ["셀피", "selfie", "이미지 생성"] },
  { match: ["noodle"], keys: ["Noodle", "누들", "타임라인", "SNS"] },
  { match: ["import", "sillytavern"], keys: ["임포트", "import", "불러오기", "SillyTavern", "실리태번"] },
  { match: ["group chat"], keys: ["그룹챗", "group chat", "단체"] },
  { match: ["memory", "summariz"], keys: ["메모리", "memory", "요약", "summarization"] },
  { match: ["macro"], keys: ["매크로", "macro"] },
];

// ── pipeline core.mjs ──
// Pure conversion core: Marinara docs markdown -> ST World Info lorebook object.
// No Node/browser-specific imports — shared by the CLI (build-lorebook.mjs)
// and the docs-tutor browser extension (bundled by its build script).



// ── Markdown parsing ──

function splitParagraphs(text) {
  return text
    .split(/\n{2,}/)
    .map((p) => p.trim())
    .filter(Boolean);
}

function chunkByParagraphs(text, max) {
  const paragraphs = splitParagraphs(text);
  const chunks = [];
  let current = "";
  for (const para of paragraphs) {
    const candidate = current ? `${current}\n\n${para}` : para;
    if (candidate.length > max && current) {
      chunks.push(current);
      current = para;
    } else {
      current = candidate;
    }
  }
  if (current) chunks.push(current);
  return chunks.length ? chunks : [text];
}

// Splits one H2 section body into one or more (title, content) leaf chunks.
function splitSection(heading, body, max) {
  const trimmed = body.trim();
  if (trimmed.length <= max) return [{ title: heading, content: trimmed }];

  const h3Matches = [...trimmed.matchAll(/^###\s+(.+)$/gm)];
  if (h3Matches.length === 0) {
    const parts = chunkByParagraphs(trimmed, max);
    return parts.map((part, i) => ({
      title: parts.length > 1 ? `${heading} (${i + 1}/${parts.length})` : heading,
      content: part,
    }));
  }

  const leaves = [];
  const intro = trimmed.slice(0, h3Matches[0].index).trim();
  if (intro) leaves.push({ title: heading, content: intro });

  for (let i = 0; i < h3Matches.length; i++) {
    const start = h3Matches[i].index;
    const end = i + 1 < h3Matches.length ? h3Matches[i + 1].index : trimmed.length;
    const subheading = h3Matches[i][1].trim();
    const subBody = trimmed.slice(start, end).replace(/^###\s+.+$/m, "").trim();
    const subTitle = `${heading} > ${subheading}`;
    if (subBody.length <= max) {
      leaves.push({ title: subTitle, content: subBody });
    } else {
      const parts = chunkByParagraphs(subBody, max);
      parts.forEach((part, j) => {
        leaves.push({
          title: parts.length > 1 ? `${subTitle} (${j + 1}/${parts.length})` : subTitle,
          content: part,
        });
      });
    }
  }
  return leaves;
}

function parseMarkdown(raw) {
  const h2Matches = [...raw.matchAll(/^##\s+(.+)$/gm)];
  const leaves = [];
  for (let i = 0; i < h2Matches.length; i++) {
    const heading = h2Matches[i][1].trim();
    if (DROP_SECTION_HEADINGS.has(heading.toLowerCase())) continue;
    const start = h2Matches[i].index + h2Matches[i][0].length;
    const end = i + 1 < h2Matches.length ? h2Matches[i + 1].index : raw.length;
    const body = raw.slice(start, end);
    leaves.push(...splitSection(heading, body, MAX_ENTRY_CHARS));
  }
  return leaves;
}

// ── Keyword derivation ──

function headingKeys(title) {
  const words = title
    .replace(/[>()/,.:;!?"'`]/g, " ")
    .split(/\s+/)
    .map((w) => w.trim())
    .filter((w) => w.length >= 3 && !STOPWORDS.has(w.toLowerCase()));
  return [...new Set(words)];
}

function augmentedKeys(title, content) {
  const haystack = `${title}\n${content}`.toLowerCase();
  const keys = new Set(headingKeys(title));
  for (const rule of KEYWORD_MAP) {
    if (rule.match.some((needle) => haystack.includes(needle.toLowerCase()))) {
      for (const k of rule.keys) keys.add(k);
    }
  }
  if (keys.size === 0) keys.add(title);
  return [...keys];
}

// ── Entry / lorebook assembly ──

// Fixed lorebook name. Deliberately version-free: the docs-tutor extension
// finds the existing lorebook by this name on re-run, so a versioned name
// would create duplicates instead of updating. (Character links reference the
// lorebook ID, so they survive entry replacement.) The docs version is
// recorded in the description and the constant entry instead.
const LOREBOOK_NAME = "Marinara Docs Tutor";

/**
 * Builds the full ST World Info object from pre-read docs.
 * @param {Array<{path: string, content: string}>} docs whitelisted docs, in TARGET_DOCS order
 * @param {string} version Marinara app/docs version, recorded in the constant entry
 * @param {string} [name] lorebook name (fixed across versions to keep links stable)
 */
function buildWorldInfo(docs, version, name = LOREBOOK_NAME) {
  const entries = {};
  let uid = 0;
  const perFileCounts = {};

  for (const doc of docs) {
    const leaves = parseMarkdown(doc.content);
    perFileCounts[doc.path] = leaves.length;

    for (const leaf of leaves) {
      const sourceTag = `[출처: ${doc.path} > ${leaf.title}]`;
      entries[String(uid)] = {
        uid,
        key: augmentedKeys(leaf.title, leaf.content),
        keysecondary: [],
        comment: `${doc.path} > ${leaf.title}`,
        content: `${sourceTag}\n${leaf.content}`,
        constant: false,
        selective: false,
        order: 100,
        disable: false,
      };
      uid++;
    }
  }

  entries[String(uid)] = {
    uid,
    key: [],
    keysecondary: [],
    comment: "항상 활성 — 버전 고지",
    content:
      `이 로어북은 Marinara Engine v${version} 문서를 기반으로 자동 생성되었습니다. ` +
      `버전별 세부사항이 확실치 않으면 지어내지 말고, 공식 문서(홈 화면 Documentation 뷰어)를 안내하세요.`,
    constant: true,
    selective: false,
    order: 100,
    disable: false,
  };
  uid++;

  const worldInfo = {
    name,
    description:
      `Marinara Engine v${version} 공식 docs에서 자동 변환된 초보자용 로어북. ` +
      `원본: docs/ (수정하지 않음).`,
    entries,
  };
  return { worldInfo, perFileCounts, total: uid };
}

// ── Validation (mirrors what importSTLorebook actually reads) ──

function validateWorldInfo(worldInfo) {
  const problems = [];
  const list = Object.values(worldInfo.entries);
  if (list.length === 0) problems.push("no entries produced");
  for (const e of list) {
    if (typeof e.content !== "string" || !e.content.trim()) {
      problems.push(`entry uid=${e.uid} has empty content`);
    }
    if (!e.constant && (!Array.isArray(e.key) || e.key.length === 0)) {
      problems.push(`entry uid=${e.uid} is non-constant but has no keys`);
    }
    if (typeof e.comment !== "string" || !e.comment.trim()) {
      problems.push(`entry uid=${e.uid} has empty comment/name`);
    }
  }
  return problems;
}

// ── runtime ──
// Runtime for the Docs Tutor Lorebook extension. The build script prepends the
// pipeline's config.mjs + core.mjs (import/export stripped), so TARGET_DOCS,
// LOREBOOK_NAME, buildWorldInfo, validateWorldInfo are in scope here.

// ══════════════════════════════════════════════════════════════
// Adapter — the ONLY module that touches Marinara internals.
// Every call below uses an undocumented-but-source-verified surface
// (verified against v2.2.1 source). If a Marinara update breaks this
// extension, fix it here and re-verify MDTL_VERIFIED_MINOR.
//
// Internal surface inventory:
//   GET    /api/health                          → { version }
//   GET    /api/docs/content?path=<rel>         → { content }   (docs.routes.ts)
//   GET    /api/characters                      → [{ id, data(JSON: name) }]
//   GET    /api/lorebooks                       → [{ id, name, characterIds }]
//   GET    /api/lorebooks/:id                   → { id, name, characterIds }
//   POST   /api/import/st-lorebook              → { success, lorebookId, entriesImported } (import.routes.ts → importSTLorebook)
//   GET    /api/lorebooks/:id/entries           → [{ id, name }]
//   POST   /api/lorebooks/:id/entries/bulk      → { ... } body { entries: CreateLorebookEntryInput[] } (native schema)
//   DELETE /api/lorebooks/:id/entries/:entryId  → 204
//   PATCH  /api/lorebooks/:id                   → updateLorebookSchema (description, characterIds, …)
//   CSRF: unsafe methods need header x-marinara-csrf: 1 (middleware/csrf-protection.ts)
// ══════════════════════════════════════════════════════════════

// Verified minor versions: every internal surface below was re-diffed against
// each of these releases (v2.3.1: lorebooks CRUD/import/extensions/docs/CSRF
// all unchanged; only scan-preview and about-me paths moved).
const MDTL_VERIFIED_MINORS = ["2.2", "2.3"];

// ══════════════════════════════════════════════════════════════
// 2.3.5 full-page 호환 심 (2026-08-01)
//
// v2.3.5의 Personal Extensions full-page 런타임은 v2.3.3 편의 헬퍼
// (addStyle / addElement / on / extensionId)를 제공하지 않는다 —
// 대신 실제 페이지 <script>로 실행되므로 document/window/fetch 원본에
// 직접 접근할 수 있다 (PersonalExtensionInjector.tsx, FullPageExtensionApi).
// 아래 심은 구 API 표면을 원본 DOM 위에 재구현하고, 생성물 전부를
// marinara.onCleanup에 등록해 v2.3.3과 같은 "언로드 시 자동 정리"
// 계약을 유지한다. 본문 코드는 무수정.
//
// marinara는 wrapper 함수의 매개변수이므로 재할당이 가능하다.
// (fullPageExtensionSource: run(extension, async (marinara) => { ... }))
// ══════════════════════════════════════════════════════════════
marinara = (() => {
  const host = marinara;
  const shim = {
    // v2.3.3: marinara.extensionId → v2.3.5: marinara.extension.id
    extensionId: host.extension.id,

    addStyle(css) {
      const el = document.createElement("style");
      el.textContent = String(css);
      el.dataset.mdtlExtension = host.extension.id;
      document.head.appendChild(el);
      host.onCleanup(() => el.remove());
      return el;
    },

    addElement(parent, tag, attrs = {}) {
      const target = typeof parent === "string" ? document.querySelector(parent) : parent;
      if (!target) return null;
      const el = document.createElement(tag);
      for (const [key, value] of Object.entries(attrs)) {
        // v2.3.3 계약: innerHTML/textContent 는 내용, 나머지는 속성
        if (key === "innerHTML") el.innerHTML = value;
        else if (key === "textContent") el.textContent = value;
        else el.setAttribute(key, value);
      }
      target.appendChild(el);
      host.onCleanup(() => el.remove());
      return el;
    },

    on(target, event, handler) {
      // v2.3.3 계약: 핸들러 오류는 잡아서 로그, 전파하지 않음
      const wrapped = (...args) => {
        try {
          return handler(...args);
        } catch (error) {
          host.log.error("[mdtl] event handler failed", error);
        }
      };
      target.addEventListener(event, wrapped);
      host.onCleanup(() => target.removeEventListener(event, wrapped));
      return wrapped;
    },
  };
  // 신형 API(log/storage/타이머/onCleanup/extension)는 그대로 통과
  return Object.freeze(Object.assign(Object.create(null), {
    version: host.version,
    extension: host.extension,
    log: host.log,
    storage: host.storage,
    setTimeout: host.setTimeout,
    clearTimeout: host.clearTimeout,
    setInterval: host.setInterval,
    clearInterval: host.clearInterval,
    onCleanup: host.onCleanup,
  }, shim));
})();

// ── 생명주기 가드 (Codex 검토 권고 1, 2026-08-01) ──
// 비활성화·해시 교체 시 호스트는 UI·타이머·리스너만 정리한다. 진행 중인
// fetch/XHR과 다단계 쓰기 작업은 여기서 스스로 중단한다: onCleanup에서
// abort + disposed 플래그를 세우고, 파괴적 단계 직전마다 확인한다.
const mdtlLifecycle = { disposed: false, abort: new AbortController() };
marinara.onCleanup(() => {
  mdtlLifecycle.disposed = true;
  mdtlLifecycle.abort.abort();
});
function mdtlCheckAlive() {
  if (mdtlLifecycle.disposed) {
    throw new Error("확장이 비활성화되어 작업을 중단했습니다. 이미 완료된 서버 변경은 되돌려지지 않습니다.");
  }
}

// 이 확장이 만든 로어북임을 식별하는 설명 마커 (core.mjs description과 동기).
const MDTL_DESC_MARKER = "docs에서 자동 변환된 초보자용 로어북";

const mdtlAdapter = {
  async request(method, path, body) {
    const headers = {};
    if (method !== "GET") headers["x-marinara-csrf"] = "1";
    if (body !== undefined) headers["Content-Type"] = "application/json";
    const res = await fetch(`/api${path}`, {
      method,
      headers,
      signal: mdtlLifecycle.abort.signal,
      ...(body !== undefined ? { body: JSON.stringify(body) } : {}),
    });
    if (res.status === 204) return null;
    const data = await res.json().catch(() => null);
    if (!res.ok) {
      const detail = data && data.error ? data.error : `HTTP ${res.status}`;
      throw new Error(`${method} /api${path} 실패: ${detail}`);
    }
    return data;
  },

  // Docs are fetched over XHR on purpose: sibling extensions (the Korean
  // maintained pack) wrap window.fetch and substitute /api/docs responses
  // with translated markdown. The lorebook build must be deterministic and
  // always read the original English docs, so we bypass fetch wrapping.
  fetchDoc(relPath) {
    return new Promise((resolve, reject) => {
      const xhr = new XMLHttpRequest();
      xhr.open("GET", `/api/docs/content?path=${encodeURIComponent(relPath)}`);
      xhr.responseType = "json";
      xhr.onload = () => {
        if (xhr.status >= 200 && xhr.status < 300 && xhr.response && typeof xhr.response.content === "string") {
          resolve({ path: relPath, content: xhr.response.content });
        } else {
          reject(new Error(`docs/${relPath} 읽기 실패 (HTTP ${xhr.status})`));
        }
      };
      xhr.onerror = () => reject(new Error(`docs/${relPath} 읽기 실패 (네트워크 오류)`));
      xhr.onabort = () => reject(new Error(`docs/${relPath} 읽기 중단됨 (확장 비활성화)`));
      mdtlLifecycle.abort.signal.addEventListener("abort", () => xhr.abort(), { once: true });
      xhr.send();
    });
  },

  async getVersion() {
    const health = await this.request("GET", "/health");
    return typeof health?.version === "string" ? health.version : null;
  },

  versionWarning(version) {
    if (!version) return "서버 버전을 확인할 수 없습니다. 계속할 수는 있지만 내부 API가 다를 수 있습니다.";
    if (!MDTL_VERIFIED_MINORS.some((minor) => version.startsWith(`${minor}.`))) {
      return `이 확장은 Marinara v${MDTL_VERIFIED_MINORS.join(".x/v")}.x에서 검증되었습니다 (현재 v${version}). 내부 API가 바뀌었을 수 있으니 실행 결과를 확인하세요.`;
    }
    return null;
  },

  async listCharacters() {
    const rows = await this.request("GET", "/characters");
    if (!Array.isArray(rows)) return [];
    return rows
      .map((row) => {
        let name = row.id;
        try {
          const data = typeof row.data === "string" ? JSON.parse(row.data) : row.data;
          if (data && typeof data.name === "string" && data.name.trim()) name = data.name;
        } catch {
          // data 파싱 실패 시 ID를 이름으로 표시
        }
        return { id: row.id, name };
      })
      .filter((c) => typeof c.id === "string" && c.id);
  },

  async findLorebookByName(name) {
    const rows = await this.request("GET", "/lorebooks");
    if (!Array.isArray(rows)) return null;
    return rows.find((row) => row.name === name) ?? null;
  },

  getLorebook(id) {
    return this.request("GET", `/lorebooks/${encodeURIComponent(id)}`);
  },

  async importSTLorebook(worldInfo) {
    const result = await this.request("POST", "/import/st-lorebook", worldInfo);
    if (!result || result.error || !result.lorebookId) {
      throw new Error(`로어북 임포트 실패: ${result?.error ?? "응답에 lorebookId 없음"}`);
    }
    return result;
  },

  listEntries(lorebookId) {
    return this.request("GET", `/lorebooks/${encodeURIComponent(lorebookId)}/entries`);
  },

  bulkCreateEntries(lorebookId, entries) {
    return this.request("POST", `/lorebooks/${encodeURIComponent(lorebookId)}/entries/bulk`, { entries });
  },

  deleteEntry(lorebookId, entryId) {
    return this.request(
      "DELETE",
      `/lorebooks/${encodeURIComponent(lorebookId)}/entries/${encodeURIComponent(entryId)}`,
    );
  },

  patchLorebook(lorebookId, patch) {
    return this.request("PATCH", `/lorebooks/${encodeURIComponent(lorebookId)}`, patch);
  },
};

// ══════════════════════════════════════════════════════════════
// Orchestration — fixed order: build → import/replace → link
// ══════════════════════════════════════════════════════════════

// Converts one ST World Info entry (core.mjs output) to the native
// CreateLorebookEntryInput shape used by POST /lorebooks/:id/entries/bulk.
// Only source-verified fields; everything omitted takes the schema default.
function mdtlToNativeEntry(stEntry) {
  return {
    name: stEntry.comment,
    content: stEntry.content,
    keys: stEntry.key,
    constant: stEntry.constant,
    order: stEntry.order,
  };
}

// Pure helper: decides how to link one character given the lorebook's current
// characterIds. PATCH /api/lorebooks/:id replaces the whole array, so the
// caller must pass the *freshest* server-side array (re-GET before each PATCH).
// Returns { status: "already-linked" } or { status: "linked", nextIds }.
function mdtlPlanLink(currentIds, characterId) {
  const ids = (Array.isArray(currentIds) ? currentIds : []).filter(
    (id) => typeof id === "string" && id,
  );
  if (ids.includes(characterId)) return { status: "already-linked" };
  return { status: "linked", nextIds: [...ids, characterId] };
}

async function mdtlRun(characterIds, onProgress) {
  if (!Array.isArray(characterIds) || characterIds.length === 0) {
    throw new Error("캐릭터를 최소 1개 선택해야 합니다.");
  }

  const report = { steps: [] };
  const step = (msg) => {
    mdtlCheckAlive();
    report.steps.push(msg);
    onProgress(report.steps.join("\n"));
  };

  // 0. 버전 확인
  const version = await mdtlAdapter.getVersion();
  const warning = mdtlAdapter.versionWarning(version);
  if (warning) step(`⚠ ${warning}`);

  // 1. docs 읽기 + 로어북 생성
  step(`docs ${TARGET_DOCS.length}편 읽는 중...`);
  const docs = [];
  const missing = [];
  for (const relPath of TARGET_DOCS) {
    try {
      docs.push(await mdtlAdapter.fetchDoc(relPath));
    } catch {
      missing.push(relPath);
    }
  }
  if (missing.length > 0) {
    throw new Error(
      `docs를 읽지 못했습니다: ${missing.join(", ")}. ` +
        `문서 구조가 바뀌었을 수 있습니다. 확장 업데이트가 필요하면 config의 TARGET_DOCS를 수정하세요.`,
    );
  }

  const { worldInfo, total } = buildWorldInfo(docs, version ?? "unknown");
  const problems = validateWorldInfo(worldInfo);
  if (problems.length > 0) {
    throw new Error(`생성된 로어북 검증 실패: ${problems.slice(0, 3).join("; ")}`);
  }
  step(`로어북 생성 완료: ${total}개 항목 (v${version ?? "?"} docs 기준)`);

  // 2. 로어북 소유권 해석 (Codex 검토 권고 2, 2026-08-01):
  //    저장된 ID → 이름+설명 마커 → 신규. 이름만 같고 마커가 없는 로어북은
  //    사용자 데이터로 간주하고 절대 건드리지 않는다.
  mdtlCheckAlive();
  let existing = null;
  const savedId = await mdtlLoadOwnedLorebookId();
  if (savedId) {
    existing = await mdtlAdapter.getLorebook(savedId).catch(() => null);
    if (!existing) step("이전에 만든 로어북이 삭제된 것으로 보입니다. 이름으로 재확인합니다.");
  }
  if (!existing) {
    const byName = await mdtlAdapter.findLorebookByName(LOREBOOK_NAME);
    if (byName) {
      const full = await mdtlAdapter.getLorebook(byName.id).catch(() => null);
      if (full && typeof full.description === "string" && full.description.includes(MDTL_DESC_MARKER)) {
        existing = full;
      } else {
        throw new Error(
          `"${LOREBOOK_NAME}" 이름의 로어북이 이미 있지만, 이 확장이 만든 것인지 확인할 수 없어 ` +
            `건드리지 않습니다. Lorebooks 패널에서 해당 로어북의 이름을 바꾸거나 삭제한 뒤 다시 실행하세요.`,
        );
      }
    }
  }
  let lorebookId;
  if (!existing) {
    const result = await mdtlAdapter.importSTLorebook(worldInfo);
    lorebookId = result.lorebookId;
    await mdtlSaveOwnedLorebookId(lorebookId);
    step(`신규 로어북 생성: "${LOREBOOK_NAME}" (${result.entriesImported}개 항목 임포트)`);
  } else {
    lorebookId = existing.id;
    await mdtlSaveOwnedLorebookId(lorebookId);
    mdtlCheckAlive();
    const oldEntries = await mdtlAdapter.listEntries(lorebookId);
    const oldIds = (Array.isArray(oldEntries) ? oldEntries : []).map((e) => e.id);
    const nativeEntries = Object.values(worldInfo.entries).map(mdtlToNativeEntry);
    await mdtlAdapter.bulkCreateEntries(lorebookId, nativeEntries);
    step(`기존 로어북에 새 항목 ${nativeEntries.length}개 추가 완료, 이전 항목 ${oldIds.length}개 정리 중...`);
    const failedDeletes = [];
    for (const entryId of oldIds) {
      mdtlCheckAlive();
      try {
        await mdtlAdapter.deleteEntry(lorebookId, entryId);
      } catch {
        failedDeletes.push(entryId);
      }
    }
    if (failedDeletes.length > 0) {
      step(
        `⚠ 이전 항목 ${failedDeletes.length}개를 정리하지 못했습니다. 로어북에 구버전 항목이 남아 있을 수 있으니 ` +
          `Lorebooks 패널에서 "${LOREBOOK_NAME}"을 열어 확인하세요. (새 항목은 모두 정상 추가됨)`,
      );
    } else {
      step(`항목 교체 완료 (${oldIds.length}개 제거, ${nativeEntries.length}개로 갱신)`);
    }
    await mdtlAdapter.patchLorebook(lorebookId, { description: worldInfo.description, enabled: true });
  }

  // 3. 캐릭터 링크 — 캐릭터별 개별 멱등, 한 캐릭터 실패가 나머지를 막지 않음(롤백 없음).
  // PATCH는 characterIds 전체 배열 교체이므로, 매 캐릭터마다 PATCH 직전에
  // 최신 배열을 다시 GET해서 병합한다 (이전 루프 반영 + 동시 변경 최소화).
  const links = [];
  for (const characterId of characterIds) {
    mdtlCheckAlive();
    try {
      const lorebook = await mdtlAdapter.getLorebook(lorebookId);
      const plan = mdtlPlanLink(lorebook?.characterIds, characterId);
      if (plan.status === "already-linked") {
        links.push({ characterId, status: "already-linked" });
      } else {
        await mdtlAdapter.patchLorebook(lorebookId, { characterIds: plan.nextIds });
        links.push({ characterId, status: "linked" });
      }
    } catch (error) {
      links.push({
        characterId,
        status: "failed",
        error: error instanceof Error ? error.message : String(error),
      });
    }
  }
  const linkedCount = links.filter((l) => l.status === "linked").length;
  const alreadyCount = links.filter((l) => l.status === "already-linked").length;
  const failedCount = links.filter((l) => l.status === "failed").length;
  step(
    `캐릭터 링크: 신규 ${linkedCount}, 이미 연결 ${alreadyCount}` +
      (failedCount > 0 ? `, 실패 ${failedCount}` : ""),
  );

  return { lorebookId, total, version, links };
}

